import heapq
import itertools


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}
        self._tickets = {}
        self._queue = []
        self._counter = itertools.count()
        self._next_id = 0

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = {"vip": vip}

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("Ticket title must not be empty")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Unknown priority: {priority}")

        ticket_id = self._next_id
        self._next_id += 1

        ticket = {
            "id": ticket_id,
            "customer": customer,
            "title": title,
            "priority": priority,
            "status": "open",  # "open" | "in_progress" | "closed"
        }
        self._tickets[ticket_id] = ticket
        self._enqueue(ticket_id)
        return ticket_id

    def _enqueue(self, ticket_id: int) -> None:
        ticket = self._tickets[ticket_id]
        priority_rank = self.PRIORITIES.index(ticket["priority"])
        # Higher priority handled first -> use negative rank
        heapq.heappush(self._queue, (-priority_rank, next(self._counter), ticket_id))

    def next_ticket(self) -> int | None:
        while self._queue:
            _, _, ticket_id = heapq.heappop(self._queue)
            ticket = self._tickets[ticket_id]
            if ticket["status"] == "open":
                ticket["status"] = "in_progress"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        ticket = self._tickets[ticket_id]
        ticket["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        ticket = self._tickets[ticket_id]
        if ticket["status"] == "closed":
            raise ValueError("Cannot reopen a closed ticket")
        ticket["status"] = "open"
        self._enqueue(ticket_id)
